#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_CONTAINERS 64
#define MAX_KEY_LEN 64
#define MAX_VAL_LEN 256
#define MAX_FIELDS 16

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
} ConfigField;

typedef struct {
    char container_id[64];
    char image[128];
    char network_mode[32];
    int cpu_shares;
    int memory_mb;
    bool privileged;
    bool host_pid;
    bool readonly_rootfs;
    char capabilities[256];
    ConfigField extra_fields[MAX_FIELDS];
    int extra_count;
} ContainerSpec;

typedef struct {
    bool allow_privileged;
    bool allow_host_pid;
    bool allow_cap_admin;
    bool enforce_readonly;
    int max_cpu_shares;
    int max_memory_mb;
} FeatureFlags;

static FeatureFlags g_flags = {
    .allow_privileged = false,
    .allow_host_pid = false,
    .allow_cap_admin = false,
    .enforce_readonly = true,
    .max_cpu_shares = 1024,
    .max_memory_mb = 4096
};

static ContainerSpec g_containers[MAX_CONTAINERS];
static int g_container_count = 0;

/* Allowlist of user-assignable fields */
static const char *user_assignable_fields[] = {
    "container_id", "image", "network_mode", "cpu_shares", "memory_mb",
    "capabilities", NULL
};

static bool is_user_assignable(const char *name) {
    for (int i = 0; user_assignable_fields[i]; i++) {
        if (strcmp(user_assignable_fields[i], name) == 0)
            return true;
    }
    return false;
}

static bool check_feature_gate(const char *field, const char *value) {
    if (strcmp(field, "capabilities") == 0 && strstr(value, "CAP_SYS_ADMIN"))
        return g_flags.allow_cap_admin;
    return true;
}

static int apply_field(ContainerSpec *spec, const char *key, const char *value) {
    /* Only allow explicitly permitted fields */
    if (!is_user_assignable(key)) {
        fprintf(stderr, "Field '%s' is not user-assignable\n", key);
        return -1;
    }

    /* Feature gate check for sensitive values */
    if (!check_feature_gate(key, value)) {
        fprintf(stderr, "Policy violation: %s=%s blocked by feature gate\n", key, value);
        return -1;
    }

    if (strcmp(key, "container_id") == 0) {
        strncpy(spec->container_id, value, sizeof(spec->container_id) - 1);
        spec->container_id[sizeof(spec->container_id) - 1] = '\0';
    } else if (strcmp(key, "image") == 0) {
        strncpy(spec->image, value, sizeof(spec->image) - 1);
        spec->image[sizeof(spec->image) - 1] = '\0';
    } else if (strcmp(key, "network_mode") == 0) {
        strncpy(spec->network_mode, value, sizeof(spec->network_mode) - 1);
        spec->network_mode[sizeof(spec->network_mode) - 1] = '\0';
    } else if (strcmp(key, "cpu_shares") == 0) {
        int v = atoi(value);
        if (v < 1 || v > g_flags.max_cpu_shares) {
            fprintf(stderr, "cpu_shares %d exceeds limit %d\n", v, g_flags.max_cpu_shares);
            return -1;
        }
        spec->cpu_shares = v;
    } else if (strcmp(key, "memory_mb") == 0) {
        int v = atoi(value);
        if (v < 1 || v > g_flags.max_memory_mb) {
            fprintf(stderr, "memory_mb %d exceeds limit %d\n", v, g_flags.max_memory_mb);
            return -1;
        }
        spec->memory_mb = v;
    } else if (strcmp(key, "capabilities") == 0) {
        strncpy(spec->capabilities, value, sizeof(spec->capabilities) - 1);
        spec->capabilities[sizeof(spec->capabilities) - 1] = '\0';
    }
    return 0;
}

/*
 * apply_spec_update: applies a batch of key=value pairs to a container spec.
 * Uses allowlist approach - only explicitly permitted fields can be set.
 * Returns 0 on success, -1 on policy violation.
 */
int apply_spec_update(ContainerSpec *spec, const char *pairs[], int count) {
    for (int i = 0; i < count; i++) {
        char key[MAX_KEY_LEN], val[MAX_VAL_LEN];
        const char *eq = strchr(pairs[i], '=');
        if (!eq) continue;
        size_t klen = eq - pairs[i];
        if (klen >= MAX_KEY_LEN) continue;
        strncpy(key, pairs[i], klen);
        key[klen] = '\0';
        strncpy(val, eq + 1, MAX_VAL_LEN - 1);
        val[MAX_VAL_LEN - 1] = '\0';

        if (apply_field(spec, key, val) != 0) {
            return -1;
        }
    }
    return 0;
}

/*
 * create_container: creates a new container from user-supplied config pairs.
 * Applies defaults then user overrides with policy enforcement.
 */
int create_container(const char *pairs[], int count) {
    if (g_container_count >= MAX_CONTAINERS) return -1;

    ContainerSpec *spec = &g_containers[g_container_count];
    memset(spec, 0, sizeof(ContainerSpec));

    /* Secure defaults - these cannot be overridden by users */
    spec->privileged = false;
    spec->host_pid = false;
    spec->readonly_rootfs = g_flags.enforce_readonly;
    spec->cpu_shares = 512;
    spec->memory_mb = 256;
    strncpy(spec->network_mode, "bridge", sizeof(spec->network_mode) - 1);

    int rc = apply_spec_update(spec, pairs, count);
    if (rc == 0) {
        g_container_count++;
    }
    return rc;
}

/* Example usage / test harness */
int main(int argc, char *argv[]) {
    /* Simulate an API request with user-supplied fields */
    const char *user_request[] = {
        "container_id=web-app-01",
        "image=nginx:latest",
        "cpu_shares=256",
        "memory_mb=512",
        "readonly_rootfs=false",
        "privileged=true"
    };
    int field_count = sizeof(user_request) / sizeof(user_request[0]);

    printf("Feature flags: privileged=%d, host_pid=%d, cap_admin=%d\n",
           g_flags.allow_privileged, g_flags.allow_host_pid, g_flags.allow_cap_admin);

    int result = create_container(user_request, field_count);
    if (result == 0) {
        ContainerSpec *c = &g_containers[0];
        printf("Container created: id=%s privileged=%d host_pid=%d readonly=%d\n",
               c->container_id, c->privileged, c->host_pid, c->readonly_rootfs);
    } else {
        printf("Container creation blocked by policy\n");
    }
    return 0;
}
